using System.Collections;
using DG.Tweening;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AfflictionEffect", menuName = "Data/Battle/Effects/Affliction Effect")]
public class AfflictionReliefEffect : Effect
{
	[Header("Affliction")]
	[SerializeField]
	private bool affliction;

	[Header("Achievement Affliction")]
	[SerializeField]
	[ShowIf("affliction")]
	private ThisisFineAchievementData thisisFineAchievementData;

	[Header("VFX")]
	[SerializeField]
	private float reliefXPosition;

	[SerializeField]
	private float afflictionXPosition;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		string localizedAtTheEndOfItsTurn = base.localizationManager.GetLocalizedAtTheEndOfItsTurn();
		string localizedEffectOwnerReceiveFormatted = base.localizationManager.GetLocalizedEffectOwnerReceiveFormatted(!affliction, amount);
		if (affliction)
		{
			if (LanguagesIndexes.IsCurrentLanguageGerman())
			{
				return localizedEffectOwnerReceiveFormatted.RemoveLast() + base.localizationManager.GetLocalizedSpace() + localizedAtTheEndOfItsTurn.RemoveLast().LowercaseFirst() + ".";
			}
			return localizedAtTheEndOfItsTurn + base.localizationManager.GetLocalizedSpace() + localizedEffectOwnerReceiveFormatted;
		}
		if (LanguagesIndexes.IsCurrentLanguageGerman())
		{
			return base.localizationManager.GetLocalizedConditionActivationThenDecreaseFormatFormatted(localizedEffectOwnerReceiveFormatted.RemoveLast(), localizedAtTheEndOfItsTurn.RemoveLast().LowercaseFirst(), this, 1);
		}
		return base.localizationManager.GetLocalizedConditionActivationThenDecreaseFormatFormatted(localizedAtTheEndOfItsTurn, localizedEffectOwnerReceiveFormatted.RemoveLast(), this, 1);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
		if (!IsVFXEnabled())
		{
			return;
		}
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		if (affliction)
		{
			if (component.IsReliefActiveSetReliefAndAfflictionActivePosition())
			{
				SetReliefAndAfflictionActivePosition(effectOwner);
			}
			else
			{
				SetVFXLocalXPosition(effectOwner, 0f);
			}
		}
		else if (component.IsAfflictionActiveSetReliefAndAfflictionActivePosition())
		{
			SetReliefAndAfflictionActivePosition(effectOwner);
		}
		else
		{
			SetVFXLocalXPosition(effectOwner, 0f);
		}
	}

	public void SetReliefAndAfflictionActivePosition(GameObject effectOwner)
	{
		if (affliction)
		{
			SetVFXLocalXPosition(effectOwner, afflictionXPosition);
		}
		else
		{
			SetVFXLocalXPosition(effectOwner, reliefXPosition);
		}
	}

	public void SetVFXLocalXPosition(GameObject effectOwner, float xPosition)
	{
		VFXHolder vFXInstanceFromVFXHolders = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHolders(effectOwner, this);
		if (vFXInstanceFromVFXHolders != null)
		{
			Transform firstChild = vFXInstanceFromVFXHolders.VFXInstance.transform.GetFirstChild();
			if (affliction)
			{
				firstChild.transform.SetLocalX(xPosition);
			}
			else
			{
				firstChild.transform.SetLocalX(xPosition);
			}
		}
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		SpawnActivationAndApplyVFX(effectOwner);
		if (affliction)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsSoulStigmaEffectActiveWithActivation();
			thisisFineAchievementData.Unlock();
		}
		else if ((bool)effectOwner.GetComponent<CompanionCorruptionStats>())
		{
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateGoddessCartoucheOmen();
		}
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfflictionReliefHealbotForcefulStreamAction(AfflictionReliefCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	public override int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
	{
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		AfflictionReliefDefaultActivation(effectAmount, effectOwner, component);
		if (!affliction)
		{
			component.IsEffectActiveAndDecreaseEffect(this, 1);
		}
		return effectAmount;
	}

	private IEnumerator AfflictionReliefCoroutine(int effectAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.3f);
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		AfflictionReliefDefaultActivation(effectAmount, effectOwner, unitEffects);
		if (!affliction)
		{
			yield return new WaitForSeconds(0.5f);
			unitEffects.IsEffectActiveAndDecreaseEffect(this, 1);
		}
		yield return new WaitForSeconds(0.5f);
	}

	private void AfflictionReliefDefaultActivation(int effectAmount, GameObject effectOwner, UnitEffects unitEffects)
	{
		unitEffects.IsEffectActive(this);
		CorruptionStats component = effectOwner.GetComponent<CorruptionStats>();
		SpawnActivationAndApplyVFX(effectOwner);
		if (affliction)
		{
			if (component is CorruptedAnimalCorruptionStats && ReferenceSingleton<SothisOmensHandler>.Instance.ActivateEtherealPlumeOmenActiveOmen())
			{
				effectAmount *= 2;
			}
			component.Corrupt(effectAmount, null, CorruptionPurifyModifierEnum.AFFLICTIONRELIEF);
		}
		else
		{
			component.Purify(effectAmount, null, CorruptionPurifyModifierEnum.AFFLICTIONRELIEF);
		}
	}

	private void SpawnActivationAndApplyVFX(GameObject effectOwner)
	{
		PlayEffectActivationSFX();
		SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 3f);
		if (IsVFXEnabled())
		{
			VFXHolder vFXInstanceFromVFXHolders = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHolders(effectOwner, this);
			if (vFXInstanceFromVFXHolders != null)
			{
				GameObject vFXInstance = vFXInstanceFromVFXHolders.VFXInstance;
				vFXInstance.GetComponentInChildren<DOTweenAnimation>().DORewind();
				vFXInstance.GetComponentInChildren<DOTweenAnimation>().DOPlay();
			}
		}
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		if (IsVFXEnabled())
		{
			UnitEffects component = effectOwner.GetComponent<UnitEffects>();
			if (affliction)
			{
				component.IsReliefActiveResetPosition();
			}
			else
			{
				component.IsAfflictionActiveResetPosition();
			}
		}
		base.RemoveEffect(effectAmount, effectOwner);
	}
}
